async (page) => {
  const sizes = [
    ['portrait', 1080, 1350, 1],
    ['wide', 1200, 1000, 0.85],
    ['sky', 300, 600, 0.28],
  ];
  const out = [];
  for (const [name, w, h, s] of sizes) {
    await page.setViewportSize({width: w, height: h});
    await page.goto(`http://localhost:62279/flyer.html?w=${w}&h=${h}&s=${s}`);
    await page.evaluate(() => window.ready);
    await page.waitForTimeout(300);
    await page.locator('#page').screenshot({path: `/private/var/folders/hf/35wnqrnj2bbb1_llbg87zlt40000gn/T/vs-807762b69c4d2303/${name}.png`});
    const info = await page.evaluate(() => {
      const inner = document.getElementById('inner');
      const scrollOver = inner.scrollHeight - inner.clientHeight;
      const r = {scrollOver, boxes:{}};
      for (const sel of ['.head h1','.photo','.cands','.cta','.steps','.foot']) {
        const b = document.querySelector(sel).getBoundingClientRect();
        r.boxes[sel] = [Math.round(b.x),Math.round(b.y),Math.round(b.width),Math.round(b.height)];
      }
      r.ctaSpan = (()=>{const e=document.querySelector('.cta span');return [e.scrollWidth, e.clientWidth];})();
      r.innerH = inner.clientHeight;
      return r;
    });
    out.push([name, info]);
  }
  return JSON.stringify(out, null, 1);
}

